fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)
    left = 0
    right = n - 1

    while (left < right):
        // Pass from left to right
        @mark<left, outline, yellow> @mark<right, outline, yellow>
        for (i = left; i < right; i += 1):
            @mark<i, highlight, green> @mark<i + 1, highlight, green>
            if (array[i] > array[i + 1]):
                swap(array[i], array[i + 1])
            end if
        end for

        // Reduce the right boundary since the largest element is now in place
        right -= 1

        // Pass from right to left
        for (i = right; i > left; i -= 1):
            @mark<i, highlight, green> @mark<i - 1, highlight, green>
            if (array[i] < array[i - 1]):
                swap(array[i], array[i - 1])
            end if
        end for

        // Increase the left boundary since the smallest element is now in place
        left += 1
    end while

    return array
end fun

