    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> pos = count[i]
        @mark<pos, highlight, green> output[pos] = array[i]
    end for

    // Copy the sorted result back to original array
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> array[i] = output[i]
    end for

    return array
