fun Dutch_National_Flag(@init<table> array):
    low = 0
    mid = 0
    high = length(array) - 1

    while (mid <= high):
        @mark<mid, outline, yellow> @mark<low, outline, yellow> @mark<high, outline, yellow>
        if (array[mid] == 0):
            @mark<mid, highlight, green> @mark<low, highlight, green>
            swap(array[low], array[mid])
            low += 1
            mid += 1
        else if (array[mid] == 1):
            @mark<mid, highlight, green>
            mid += 1
        else:
            @mark<mid, highlight, green> @mark<high, highlight, green>
            swap(array[mid], array[high])
            high -= 1
        end if
    end while

    return array
end fun

