fun Find_Majority_Element(@init<table> nums):
    n = length(nums)
    candidate = 0
    count = 0

    // Boyer-Moore Voting Algorithm
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (count == 0):
            @mark<i, highlight, green> candidate = nums[i]
        end if
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        else:
            @mark<i, highlight, red> count -= 1
        end if
    end for

    // Check if candidate is actually majority
    count = 0
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if
    end for

    // Return candidate if it appears more than n/2 times
    @mark<n, text, yellow> if (count > floor(n / 2)):
        @mark<n, highlight, green> return candidate
    else:
        @mark<n, highlight, red> return -1
    end if
end fun

