    if (n > 1):
        mid = floor(n / 2)
        left = arr(mid, 0)
        right = arr(n - mid, 0)

        // Copy left half
        for (i = 0; i < mid; i += 1):
            left[i] = array[i]
        end for

        // Copy right half
