fun Hoare_Partition(@init<table> array, low, high):
    pivot = array[low]
    i = low - 1
    j = high + 1
    @mark<low, outline, yellow> @mark<pivot, text, green>
    while (true):
        i += 1
        while (array[i] < pivot):
            i += 1
        end while
        j -= 1
        while (array[j] > pivot):
            j -= 1
        end while
        @mark<i, outline, yellow> @mark<j, outline, yellow>
        if (i >= j):
            return j
        end if
        @mark<i, highlight, green> @mark<j, highlight, green>
        swap(array[i], array[j])
    end while
end fun

fun Quick_Sort(@init<table> array, low, high):
    if (low < high):
        @mark<low, outline, yellow> @mark<high, outline, yellow>
        p = Hoare_Partition(array, low, high)
        @mark<p, outline, yellow>
        Quick_Sort(array, low, p)
        Quick_Sort(array, p + 1, high)
    end if
end fun

