fun Remove_Duplicates(@init<table> array):
    @log<info, "Starting duplicate removal">
    if (length(array) == 0):
        return 0
    end if

    // Index for the position of the next unique element
    write_index = 1

    // Start from index 1 since first element is always unique
    for (i = 1; i < length(array); i += 1):
        @mark<i, outline, yellow> 
        @mark<write_index - 1, highlight, green>
        if (array[i] != array[write_index - 1]):
            @mark<i, text, red>
            array[write_index] = array[i]
            write_index += 1
        end if
    end for

    // Return count of unique elements
    return write_index
end fun

