// Quickselect with Lomuto Partitioning

a1 = arr[5, 1, 4, 2, 8]

fun Partition(@init<table> array, low, high):
    // Choose the rightmost element as pivot
    pivot = array[high]
    // Index of smaller element (indicates right position of pivot)
    i = low - 1

    for (j = low; j < high; j += 1):
        // If current element is smaller than or equal to pivot
        @mark<j, outline, yellow> if (array[j] <= pivot):
            @mark<j, highlight, green> i += 1
            @swap<i, j>
        end if
    end for

    // Place pivot in its correct position
    @swap<i + 1, high>
    return i + 1
end fun

fun Quickselect(@init<table> array, low, high, k):
    // Base case
    if (low == high):
        return array[low]
    end if

    // Partition the array and get pivot index
    pivotIndex = Partition(array, low, high)

    // If pivot is the k-th smallest element
    @mark<pivotIndex, outline, yellow> if (pivotIndex == k - 1):
        return array[pivotIndex]
    end if

    // If pivot is greater than k-th element, search left subarray
    if (pivotIndex > k - 1):
        return Quickselect(array, low, pivotIndex - 1, k)
    end if

    // Else search right subarray
    return Quickselect(array, pivotIndex + 1, high, k)
end fun

