fun Selection_Sort(@init<table> array):
    n = length(array)
    for (i = 0; i < n - 1; i += 1):
        @mark<i, outline, yellow> max_index = i
        for (j = i + 1; j < n; j += 1):
            @mark<j, outline, yellow> if (array[j] > array[max_index]):
                @mark<j, highlight, green> max_index = j
            end if
        end for
        @mark<i, highlight, green> if (max_index != i):
            @swap<i, max_index> swap(array[i], array[max_index])
        end if
    end for
    return array
end fun

